\documentclass[tikz, border=5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows, intersections} 
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty} 

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{tikzpicture}

% a and b
\def\a{7}
\def\b{5}
\def\rot{-30}

\pgfmathsetmacro{\myWidth}{max(\a,\b)+0.5};

\begin{axis}[
trig format plots=rad,
tick label style={font=\footnotesize},
label style={font=\small},
tick style={draw=black, thick},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
%grid = both,
xmin = -\myWidth,
xmax = \myWidth,
ymin = -\myWidth,
ymax = \myWidth,    
xtick = {0}, xticklabels = {},
ytick = {0}, yticklabels = {},  
xlabel = {$x$},
ylabel = {$y$},
%% Here, we can control the positioning of each individual tick.
%x tick label style={xshift={(\tick==-5)*-5pt}},
xlabel style={below right},
ylabel style={above right},
every axis x label/.style={at={(ticklabel* cs:1.02)},anchor=west,},
every axis y label/.style={at={(ticklabel* cs:1.02)},anchor=south,}
]

% Draw the ellipce
\plot[rotate around={\rot:(axis cs:0,0)}, domain={0}:{2*pi}, samples=200, color=deepskyblue, very thick, fill=lightblue!50, fill opacity=0.3]
	({\a*cos(x)},{\b*sin(x)});

% Draw the radii
\draw[rotate around={\rot:(axis cs:0,0)}, -latex, orangepeel, very thick, opacity=1] 
	(axis cs:0,0) -- (axis cs:{\a},{0}) node[midway, orangepeel!80!black, above] {\small $\a$} node[right] {$A\mathbf{v}_1$};
\draw[rotate around={\rot:(axis cs:0,0)}, -latex, fadedpink, very thick, opacity=1] 
	(axis cs:0,0) -- (axis cs:{0},{\b}) node[midway, fadedpink!80!black, left] {\small $\b$} node[above] {$A\mathbf{v}_2$};;

\end{axis}
\end{tikzpicture}
\end{document}

